function decodePlain(raw){try{return new TextDecoder().decode(Uint8Array.from(atob(raw),c=>c.charCodeAt(0)))}catch{return ''}}
function upstreamBrief(){return resources().find(r=>r.resourceType==='Binary'&&r.meta?.source==='metriport:ai-generated-brief'&&r.contentType==='text/plain')}
function compositionSections(c){return (c.section||[]).flatMap(s=>[s,...compositionSections(s)])}
