function orderedVisits(){return resources().filter(r=>r.resourceType==='Encounter').sort((a,b)=>(Date.parse(date(b))||0)-(Date.parse(date(a))||0))}
function visitRecords(v){const ref='Encounter/'+v.id;return resources().filter(r=>r.encounter?.reference===ref||r.context?.reference===ref)}
