function prioritySeries(){return trendSeries().sort((a,b)=>Number(isFlagged(b.points.at(-1)))-Number(isFlagged(a.points.at(-1)))||Date.parse(date(b.points.at(-1)))-Date.parse(date(a.points.at(-1))))}
