async function prepare(failure=false,forceMode){if(busy)return;if(!resources().length||!data.patient){$('notice').textContent='The saved sandbox patient and bundle are required for this demo.';return}busy=true;invalidate();work.tasks={};work.seen={};work.events=[];work.problem=null;work.deliveryFailed=false;work.booked=true;work.phase='matching';if(forceMode)work.mode=forceMode;work.runMode=failure?'simulation':work.mode;log('Appointment booked','Simulated appointment: Chris Smith, Nov 3 at 09:00.');render();try{if(!identityMatches())throw Error('Saved patient ID, name or birth date does not match the appointment fixture. Retrieval stopped.');log('Existing patient matched','Sandbox patient ID, name and birth date match. No new patient was created.');work.phase='retrieving';save();render();if(failure){log('Document metadata delivered',`${data.documents?.documents?.length||0} saved document references used for rehearsal.`,'simulation');work.deliveryFailed=true;work.phase='review';log('Bundle delivery interrupted','Synthetic failure. Last successful history retained; delivery follow-up created.','simulation');$('notice').textContent='Failure rehearsal: cached history remains available. Retry the simulated delivery to continue.'}else{if(work.mode==='live'){if(!data.keyAvailable)throw Error('Sandbox key is unavailable. No provider call was made.');await provider('poll');if(networkIncomplete())throw Error('Network query is unfinished or reports errors. Available history is retained; retry reads after reviewing provider status.');await provider('records');const prior=data.bundleRetrievedAt;await provider('fhir-poll');if(!data.bundleRetrievedAt||data.bundleRetrievedAt===prior)throw Error('No newly delivered bundle was confirmed. Previously loaded synthetic history remains visible.')}else log('Synthetic bundle processed','Replay of authored synthetic FHIR data. No provider call.','replay');if(!identityMatches())throw Error('Returned patient identity does not match the appointment. Do not prepare the chart.');work.phase='checking';log('Structured history available',`${resources().length} resources received; source references retained.`,work.mode==='live'?'provider':'replay');work.phase='review';work.snapshot=data.bundleRetrievedAt;log('Review topics created',`${issues().length} topics detected by explicit data-quality and review rules.`);$('notice').textContent=work.mode==='live'?'Sandbox reads completed. Review the flagged history before preparing the handoff.':''}}catch(e){work.problem=e.message;work.phase='review';log('Retrieval held',e.message);$('notice').textContent=e.message}finally{busy=false;save();render()}}
function recoverDelivery(){if(busy)return;work.deliveryFailed=false;delete work.tasks.delivery;invalidate();work.phase='review';log('Simulated delivery recovered','Reused the saved bundle. No provider call; existing review dispositions preserved.','simulation');save();if($('evidence').open)$('evidence').close();render();$('notice').textContent='Simulated delivery recovered. Review topics still need attention.'}
function handoff(){return {purpose:'Sandbox implementation demonstration; not clinical advice',appointment:{simulated:true,name:'Chris Smith',start:'2026-11-03T09:00:00',timeZone:'Clinic demo local time'},mode:work.runMode,patientId:data.patient?.id,preparedAt:work.preparedAt,readiness:readiness(),bundleRetrievedAt:data.bundleRetrievedAt,resourceCount:resources().length,topics:issues().map(i=>({id:i.id,title:i.title,detail:i.detail,publicSource:i.publicSource||null,disposition:taskState(i.id),evidence:i.records.map(r=>({resourceType:r.resourceType,id:r.id,date:date(r),sourceDocumentIds:sourceDocs(r).map(d=>d.id)}))})),notes:work.notes,events:work.events,limitations:['Simulated booking; no live EHR connector or writeback','Dedicated pharmacy and lab feeds not enabled','Assigned follow-ups are unresolved; historical data does not establish current clinical status']}}
function medicationFor(r){if(r.resourceType==='Medication')return r;if(!['MedicationStatement','MedicationRequest'].includes(r.resourceType))return null;return resolve(r.medicationReference?.reference)||(r.medicationCodeableConcept?{resourceType:'Medication',code:r.medicationCodeableConcept}:null)}
function medicationCode(r){return medicationFor(r)?.code?.coding?.find(c=>c.system==='http://www.nlm.nih.gov/research/umls/rxnorm')?.code}
function medicationRef(r){const med=medicationFor(r);if(!med)return null;const code=medicationCode(r),ref=PUBLIC_MEDICATION_REFERENCE.entries.find(e=>e.code===code);if(!ref)return {code,sourceName:concept(med.code),status:'unresolved',matchNote:'No reviewed public reference is cached for this medication.'};if(concept(med.code).toLowerCase()!==ref.sourceName.toLowerCase())return {...ref,status:'mismatch',reference:null,matchNote:'The current chart display differs from the reviewed source name. Enrichment is held pending another identity check.'};return ref}
function publicLink(text,url){const a=E('a',text);try{const u=new URL(url);if(u.protocol!=='https:'||!['rxnav.nlm.nih.gov','dailymed.nlm.nih.gov','medlineplus.gov'].includes(u.hostname))return E('span','Reference link unavailable');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer'}catch{return E('span','Reference link unavailable')}return a}
function medicationRecords(){return resources().filter(r=>r.resourceType==='Medication'||(['MedicationStatement','MedicationRequest'].includes(r.resourceType)&&r.medicationCodeableConcept))}
function medicationIssues(){const meds=medicationRecords(),held=meds.filter(r=>!['matched','compatible'].includes(medicationRef(r)?.status));const out=[];if(held.length)out.push({id:'medication-identity',title:'Verify drug identities before applying reference guidance',type:'Public terminology check',detail:`${held.length} medication concepts have a code/name discrepancy or unresolved identity. Public information is withheld for those entries. The original chart has not been changed.`,records:held});
 const statements=resources().filter(r=>r.resourceType==='MedicationStatement'&&r.status==='active'&&medicationRef(r)?.status==='matched');const ace=statements.filter(r=>medicationCode(r)==='314076'),nsaid=statements.filter(r=>medicationCode(r)==='197805');
 if(ace.length&&nsaid.length)out.push({id:'lisinopril-ibuprofen',title:'Confirm whether lisinopril and ibuprofen are taken together',type:'Potential interaction · current use unconfirmed',detail:'Both appear in historical statements marked active. The lisinopril label describes kidney-related risk in susceptible patients and reduced blood-pressure effect with NSAIDs. This is a reconciliation question, not evidence of concurrent use or harm. A clinician or pharmacist should assess the complete current list.',records:[...ace,...nsaid],publicSource:PUBLIC_MEDICATION_REFERENCE.entries.find(r=>r.code==='314076').reference.labelUrl});return out}
function referenceBody(ref){const box=E('div',undefined,'med-reference');box.append(E('p',ref.matchNote,'tiny'));if(ref.canonicalName){const compare=E('div',undefined,'identity-compare');compare.append(E('span','PUBLIC RXNORM CONCEPT','eyebrow'),E('strong',ref.canonicalName),E('small',`RxCUI ${ref.code} · ${ref.termType||'type unavailable'}`));box.append(compare)}
 if(!['matched','compatible'].includes(ref.status)||!ref.reference){box.append(E('p','Medication-specific guidance is held until identity is reconciled. A different name, strength or formulation can change the applicable warnings.','warning'));if(ref.sourceUrl)box.append(publicLink('Inspect NLM terminology response ↗',ref.sourceUrl));return box}
 const r=ref.reference;[['What it is used for',r.purpose],['Selected side effects',r.sideEffects],['Contraindications / restrictions',r.contraindications],['Important cautions',r.cautions],['Interaction considerations',r.interactions]].forEach(([title,text])=>{const section=E('div',undefined,'reference-section');section.append(E('h3',title),E('p',text));box.append(section)});const sources=E('div',undefined,'reference-sources');sources.append(publicLink('Read full DailyMed label ↗',r.labelUrl),publicLink('Verify RxNorm concept ↗',ref.sourceUrl));if(r.education)sources.append(publicLink('Plain-language guide · MedlinePlus.gov ↗',r.education));box.append(sources,E('p',`${r.scope} Label published ${r.labelPublished}, version ${r.labelVersion}. Retrieved ${human(r.checkedAt)}.`,'tiny'));return box}
function showMedication(r){if($('evidence').open)$('evidence').close();const ref=medicationRef(r);if(!ref)return;$('dialog-label').textContent='PUBLIC MEDICATION REFERENCE';$('evidence-title').textContent=label(r);$('evidence-body').replaceChildren(E('p','General reference information. The chart does not establish the patient’s present use or reason for treatment.','tiny'),referenceBody(ref));$('evidence').showModal()}
function renderMedications(host){const meds=medicationRecords(),available=meds.filter(r=>['matched','compatible'].includes(medicationRef(r)?.status));const p=panel('Medication intelligence',`${available.length} references available · ${meds.length-available.length} identities need review. Public sources checked ${human(PUBLIC_MEDICATION_REFERENCE.checkedAt)}.`);const intro=E('div',undefined,'med-report-intro');intro.append(E('p','Understand the medicine, verify the identity, then consider the patient. General label information stays separate from chart evidence.'),E('p','This is a limited reference and reconciliation layer, not a comprehensive drug-interaction checker.','tiny'));p.append(intro);host.append(p);
 const links=medicationIssues();links.forEach(i=>p.append(issueCard(i)));
 if(!meds.length)p.append(E('p','No medication concepts were supplied in this bundle. This is not confirmation that the patient takes no medicines.','empty'));const list=panel('Public references & identity checks','The original chart labels are preserved. Expand an entry for the verified public concept, selected cautions, and source links.');meds.sort((a,b)=>Number(!['matched','compatible'].includes(medicationRef(a).status))-Number(!['matched','compatible'].includes(medicationRef(b).status))||label(a).localeCompare(label(b))).forEach(m=>{const ref=medicationRef(m),details=E('details',undefined,'medication-card'),summary=E('summary');summary.append(E('strong',label(m)),E('span',ref.status==='matched'?'Name / strength / form agree':ref.status==='compatible'?'Form agrees · brand unverified':ref.status==='mismatch'?'Identity discrepancy':'Identity unresolved','match-label '+(['matched','compatible'].includes(ref.status)?'matched':'held')));details.append(summary,referenceBody(ref));list.append(details)});host.append(list);host.append(E('p','MedlinePlus Connect was unavailable from this machine. Education links shown here were separately reviewed; no API matches are claimed. Public API requests used medication codes only, without patient identifiers or clinical history.','tiny'))}

function handoffText(){const h=handoff();return ['VISIT PREPARATION | CHRIS SMITH','Independent sandbox demonstration',`Appointment: Nov 3, 2026 at 09:00 (simulated clinic time)`,`Status: ${h.readiness}`,`Prepared: ${h.preparedAt||'Not yet prepared'}`,`Data retrieved: ${h.bundleRetrievedAt||'Not available'}`,`Run mode: ${h.mode||'Not run'}`,'','CARE-TEAM NOTE',h.notes||'No handoff note recorded.','','REVIEW & FOLLOW-UP',...h.topics.flatMap((i,n)=>[`${n+1}. ${i.title}`,i.detail,...(i.publicSource?['Public label: '+i.publicSource]:[]),`Disposition: ${i.disposition.state} | Owner: ${i.disposition.owner||'Unassigned'}`,i.disposition.note||'No review note recorded.',...i.evidence.map(r=>`Source: ${r.resourceType}/${r.id} | ${r.date||'Undated'} | Documents: ${r.sourceDocumentIds.join(', ')||'Unresolved'}`),'']),'BOUNDARIES',...h.limitations].join('\n')}
function previewHandoff(){$('dialog-label').textContent='LOCAL HANDOFF';$('evidence-title').textContent='Care-team handoff';const b=$('evidence-body');b.replaceChildren(E('p',readiness(),'status amber'),E('h3','Chris Smith · Nov 3 at 09:00'),E('p',work.notes||'No handoff note recorded.','handoff-preview-note'));issues().forEach(i=>{const s=taskState(i.id),card=E('div',undefined,'source-card');card.append(E('strong',i.title),E('p',`${s.state} · ${s.owner||'Unassigned'}`),E('p',s.note||'No disposition recorded.'));b.append(card)});b.append(E('p','Independent sandbox demonstration. Assigned follow-ups remain unresolved. No EHR writeback.','tiny'));$('evidence').showModal()}
function exportHandoff(){const blob=new Blob([handoffText()],{type:'text/plain'}),url=URL.createObjectURL(blob),a=E('a');a.href=url;a.download='chris-smith-visit-handoff.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function load(){try{const r=await fetch('/api/sandbox');if(!r.ok)throw Error('Saved sandbox state could not be loaded.');data=await r.json();if(work.ruleVersion!=='continuity-v2'){invalidate();work.ruleVersion='continuity-v2';if(work.booked)work.phase='review';save()}if(work.snapshot&&work.snapshot!==data.bundleRetrievedAt){work.tasks={};work.seen={};invalidate();work.phase=work.booked?'review':'idle';work.snapshot=data.bundleRetrievedAt;save()}if(!work.booked) await prepare(false,'replay'); else render()}catch(e){$('notice').textContent=e.message}}
$('close-evidence').onclick=()=>$('evidence').close();

// Curated navigation mapping only. It does not classify disease, severity or laterality.
function kidneyConditions(){return resources().filter(r=>r.resourceType==='Condition'&&r.code?.coding?.some(c=>c.system==='http://hl7.org/fhir/sid/icd-10-cm'&&['N18.3','N18.31','N18.32'].includes(c.code))&&/chronic kidney disease/i.test(label(r)))}
function renderBodyMap(host){host.append(E('p','Schematic navigation, not imaging or a disease-severity map. Only reviewed code-and-label matches are highlighted.','tiny'));const layout=E('div',undefined,'body-layout'),art=svg('svg',{viewBox:'0 0 220 330',role:'group','aria-label':'Schematic front-facing body. Kidney history navigation; position is illustrative, not patient-specific.'});art.append(svg('circle',{cx:110,cy:33,r:23,class:'body-outline'}),svg('path',{d:'M91 61 L129 61 L151 81 L171 166 Q173 179 163 181 Q154 182 151 170 L135 118 L139 196 L130 304 Q129 317 117 314 L110 220 L103 314 Q91 317 90 304 L81 196 L85 118 L69 170 Q66 182 57 181 Q47 179 49 166 L69 81 Z',class:'body-outline'}));const kidney=kidneyConditions(),g=svg('g',{role:'button',tabindex:'0','aria-label':`Kidney history: ${kidney.length} mapped condition records. Open sources.`,class:'anatomy-target'});g.append(svg('rect',{x:70,y:120,width:80,height:44,fill:'transparent','pointer-events':'all'}),svg('path',{d:'M91 126 C72 123 73 157 89 157 C100 157 99 147 92 143 C100 138 101 129 91 126 Z',class:kidney.length?'organ-mapped':'organ-unmapped'}),svg('path',{d:'M129 126 C148 123 147 157 131 157 C120 157 121 147 128 143 C120 138 119 129 129 126 Z',class:kidney.length?'organ-mapped':'organ-unmapped'}));const open=()=>showPanel('Kidney history',h=>{h.append(E('p','Historical CKD records matched by ICD-10-CM code and display. Different stages and dates are retained; no current stage or affected side is inferred.','tiny'));kidney.forEach(r=>h.append(record(r)));if(!kidney.length)h.append(E('p','No reviewed match. This does not exclude kidney disease.','empty'));h.append(button('Review all measurements',()=>showPanel('Measurements',body=>prioritySeries().forEach(s=>body.append(button(s.name,()=>showPanel(s.name,b=>{renderTrendSummary(b,s);renderGraph(b,s)}),'measurement-link')))),'wide'))});g.onclick=open;g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}};art.append(g,svg('path',{d:'M83 101 Q108 93 134 105 L124 119 Q98 123 83 112 Z',class:'organ-unmapped'}),svg('text',{x:110,y:326,'text-anchor':'middle',class:'axis'},'Schematic front view'));const copy=E('div');copy.append(E('h3','Find the evidence by body region'),button(`Kidneys · ${kidney.length} condition records`,open,'wide'),E('p','Blue = mapped history, not severity or current disease activity. Both kidney shapes are one navigation target; laterality is not inferred.','tiny'),E('p','Liver shown in gray: this prototype has no reviewed liver mapping. Gray does not mean healthy. Other systems are not yet mapped.','tiny'),button('Browse all conditions',()=>{ $('evidence').close();section='Profile';render()},'wide'));layout.append(art,copy);host.append(layout)}
